import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math3.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector.ebeMultiply
 */
public class OpenMapRealVector_ebeMultiply_TriageGen2Test {

    private static final double EPSILON = 1e-10;







    @Test
    public void testEbeMultiply_SpecialCases_NaNAndInfinity() {
        // The comment in the source code mentions MATH-803: 
        // 0d * NaN or 0d * Infinity should not simply be ignored if we want to be mathematically accurate 
        // regarding the propagation of NaN/Inf in certain contexts, 
        // although in standard IEEE 754, 0.0 * NaN is NaN.

        // Note: The provided code snippet actually CUTS OFF before the special cases handling.
        // However, to maximize coverage of the logic described in the comment:

        OpenMapRealVector v1 = new OpenMapRealVector(3);
        v1.setEntry(0, 0.0); // This is a "zero" entry in the sparse map
        v1.setEntry(1, 2.0);

        RealVector v2 = new ArrayRealVector(new double[]{Double.NaN, Double.POSITIVE_INFINITY, 5.0});

        OpenMapRealVector result = v1.ebeMultiply(v2);

        // According to the comment, the loop handles non-zero entries.
        // For index 0, it's not in the iterator, so it stays 0.0 in the result.
        // However, if the "special cases" code (not shown in snippet but implied) 
        // handles the 0 * NaN case:

        Assert.assertEquals(2.0, result.getEntry(1), EPSILON);

        // Testing the behavior of the existing loop:
        // If v1[0] is 0.0, it is NOT in the entries iterator.
        // Therefore, result.setEntry(0, 0.0 * NaN) is never called in the loop.
        // The result[0] remains 0.0 (the default value).
        Assert.assertEquals(0.0, result.getEntry(0), EPSILON);
    }




}

package org.apache.commons.math3.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.MathArithmeticException;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math3.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector.ebeMultiply
 */
public class OpenMapRealVector_ebeMultiply_TriageGen2Test {

    private static final double EPSILON = 1e-10;











    @Test
    public void testEbeMultiply_Identity() {
        double[] vals = {1.0, 2.0, 3.0};
        OpenMapRealVector v1 = new OpenMapRealVector(vals);
        RealVector v2 = new ArrayRealVector(new double[]{1.0, 1.0, 1.0});

        OpenMapRealVector result = v1.ebeMultiply(v2);

        for (int i = 0; i < vals.length; i++) {
            Assert.assertEquals(vals[i], result.getEntry(i), EPSILON);
        }
    }
}
